import os
import re
from time import sleep
from ute_tshark import ute_tshark
from subprocess import CalledProcessError
from ute_ipsec.commissioning import Commissioning
from ute_ipsec.exceptions import IpSecConnectionError, IpSecDisabledError, IpSecStateError, EmergencyBypassStateError, IKE_SA_INIT_RequestError
from ute_ipsec.trs_config import TrsConfig
from ute_ipsec.builder import CommandBuilder
from ute_ipsec.fsm_access import FsmAccess


class CommonIpsec(object):

    """ All common methods in this class"""

    def _parse_connections_states(self, connections, console_output):
        connection_status_dictionary = {}
        for connection_number in connections:
            connection_status, connection_espspi = self._parse_state(connection_number, console_output)
            connection_status_dictionary[connection_number] = (connection_status, connection_espspi)
        return connection_status_dictionary

    def _parse_state(self, connection_number, console_output):
        conn_stat_regex = r'conn{}.*?ESTABLISHED'.format(connection_number)
        conn_espspi_regex = r'conn{}.*?INSTALLED.*ESP SPIs: ([a-f0-9]+_i [a-f0-9]+_o)'.format(connection_number)
        connection_status = 'established' if re.search(conn_stat_regex, console_output) else 'not established'
        match = re.search(conn_espspi_regex, console_output)
        connection_espspi = match.group(1) if match else None
        return connection_status, connection_espspi

    def _assert_state(self, expected_state, found_state):
        if found_state != expected_state.strip().lower():
            raise IpSecStateError('Expecting {} , but found {}'.format(expected_state, found_state))


class BTSIpsec(CommonIpsec):

    """ All bts Ipsec methods in this class"""

    def __init__(self, executor, sec_gw_ip):
        self.executor = executor
        self.commissioning = Commissioning()
        self.trs_config = TrsConfig()
        self.fsm_access = FsmAccess()
        self.ute_tshark = ute_tshark()
        self.sec_gw_ip = sec_gw_ip

    def configure_policies(self, number_of_vlans, ip_version, configuration, config_file):
        """Configures policies on bts"""
        if config_file == 'default':
            self.commissioning.configure_policies_on_bts(number_of_vlans, ip_version, configuration)

    def enable(self):
        """Enables Ipsec on BTS"""
        self._start_capture()
        self.commissioning.enable_on_bts()
        self._stop_capture()

    def check_all_states(self):
        """Checks ipsec and connections states"""
        self.check_state('enabled')
        self.verify_connections_established()

    def check_state(self, expected_state):
        """Raises error if the expected ipsec state is not found"""
        found_state = self._get_state()
        self._assert_state(expected_state, found_state)

    def verify_connections_established(self, conn=(50, 60, 70)):
        """ Raises exception if connections are not established on BTS"""
        states = self.get_connections_states(conn)
        if any((status == 'not established' or espspi is None for status, espspi in states.values())):
            raise IpSecConnectionError('On BTS', states)

    def _start_capture(self):
        self._remove_capture_file('/tmp/isakmp_capture.pcap')
        self.ute_tshark.setup_tshark(interface='eth3', log_dir='/tmp', log_name='isakmp_capture.pcap',
                                     ssh_ip=self.sec_gw_ip, ssh_username='ute', ssh_password='ute')
        self.ute_tshark.start_capturing()

    def _stop_capture(self):
        sleep(60)
        self.ute_tshark.stop_capturing()
        self.ute_tshark.teardown_tshark()

    def verify_ipsec_traffic(self, ip_version, configuration):
        """ Verifies for IKE_SA_INIT Request and Response Messages after enabling ipsec """
        tunnel_endpoints = self._get_tunnel_endpoints(ip_version, configuration)
        for i in range(len(tunnel_endpoints)):
            self._verify_ipsec_traffic_for_each_plane(ip_version, tunnel_endpoints[i])
        self._remove_capture_file('/tmp/isakmp_capture.pcap')

    def _get_tunnel_endpoints(self, ip_version, configuration):
        if configuration == 'basic':
            if ip_version == 4:
                tunnel_endpoints = ['10.0.3.210', '10.0.3.214', '10.0.3.218']
            elif ip_version == 6:
                tunnel_endpoints = ['fc00::3:7', 'fc00::3:b', 'fc00::3:f']
        elif configuration == '8 ip':
            tunnel_endpoints = ['10.0.3.234', '10.0.3.238', '10.0.3.242']
        return tunnel_endpoints

    def _remove_capture_file(self, file_path):
        self.executor.execute_command_on_secgw("sudo rm -rf " + file_path)

    def _verify_ipsec_traffic_for_each_plane(self, ip_version, plane_ip):
        capture_content = self._filter_isakmp_traffic(ip_version, plane_ip)
        isakmp_msgs_list = self._create_isakmp_messages_list(capture_content)
        response_index = isakmp_msgs_list.index('Response')
        self._check_for_second_ike_sa_init_request_from_enb(response_index, isakmp_msgs_list)

    def _filter_isakmp_traffic(self, ip_version, plane_ip):
        if ip_version == 4:
            cmd = "tshark -r /tmp/isakmp_capture.pcap -Y 'isakmp.exchangetype == 34 " + "&& ip.addr==" + plane_ip + "'" + " 2>/dev/null"
        elif ip_version == 6:
            cmd = "tshark -r /tmp/isakmp_capture.pcap -Y 'isakmp.exchangetype == 34 " + "&& ipv6.addr==" + plane_ip + "'" + " 2>/dev/null"
        return self.executor.execute_command_on_secgw(cmd)

    def _create_isakmp_messages_list(self, capture_content):
        msgs_list = []
        for i in range(len(capture_content.split('\n'))):
            msg = (capture_content.split('\n')[i].split(' ')[-1])
            if msg != '':
                msgs_list.append(msg)
        return msgs_list

    def _check_for_second_ike_sa_init_request_from_enb(self, index, msgs_list):
        flag = 0
        for i in range(index + 1, len(msgs_list)):
            if msgs_list[i] == 'Request':
                flag = 1
        if flag == 0:
            return
        elif flag == 1:
            raise IKE_SA_INIT_RequestError(
                'ENodeB sent IKE_SA_INIT Request after receiving IKE_SA_INIT Response from SecGw')

    def _get_state(self):
        """Raises error if the expected ipsec state is not found"""
        _, rc = self.get_ipsec_status()
        return 'enabled' if rc == 0 or rc == 1 else 'disabled'

    def get_connections_states(self, conn=(50, 60, 70)):
        """Returns connection(s) status dictionary"""
        console_output, rc = self.get_ipsec_status()
        if rc == 0 or rc == 1:
            return self._parse_connections_states(conn, console_output)
        else:
            raise IpSecDisabledError('on bts')

    def get_ipsec_status(self):
        """Returns ipsec status and the rc. Redirecting to file is required to capture output"""
        _, rc = self.fsm_access.execute_command('ipsec status 2>&1 > /tmp/ipsec_states.txt')
        console_output, _ = self.fsm_access.execute_command('cat /tmp/ipsec_states.txt')
        return console_output, rc

    def emergency_bypass_state_should_be(self, expected_state):
        """verifies if the emergency bypass state is as expected"""
        found_state = ''
        # with self.fsm_access.new_fsmaccess_session():
        for num_of_try in range(1, 10):
            found_state = self._get_embypass_state()
            found_state = found_state.strip()
            if found_state.lower() == expected_state.lower():
                return
        raise EmergencyBypassStateError('Expecting {} , but found {}'.format(expected_state, found_state))

    def disable(self):
        """Stops ipsec on BTS"""
        self.commissioning.disable_ipsec_on_bts()

    def remove_policies_and_routes(self, number_of_vlans, ip_version, config_file):
        """Removes Ipsec policies and Ip Routes on BTS"""
        number_of_vlans = self._get_no_of_vlans()
        if config_file == 'default':
            self.commissioning.delete_ipsec_policies_on_bts(ip_version, config_file)
            self.commissioning.update_app_addr_with_default(number_of_vlans, ip_version)
            if self.trs_config.is_vlan_existing(ip_version):
                self.commissioning.delete_ip_routes_on_bts(number_of_vlans, ip_version)
        elif config_file != 'default':
            self.commissioning.commission_with_default_parameters()

    def turn_on_emergency_bypass_feature(self, ip_version):
        """Enables the emergency by-pass feature on BTS"""
        self.commissioning.turn_on_emergency_bypass_feature(ip_version)

    def turn_off_emergency_bypass_feature(self):
        """Disables the emergency by-pass feature on BTS"""
        self.commissioning.turn_off_emergency_bypass_feature()

    def exit_emergency_bypass(self):
        """Exits emergency bypass from Active state"""
        self.commissioning.exit_emergency_bypass()

    def modify_ipsec_policy_parameters_on_bts(self, connections, **parameters):
        """Modifies Ipsec policy parameters for the specified connection(s) with the specified parameter name & values on BTS"""
        self.commissioning.modify_ipsec_policy_parameters_on_bts(connections, **parameters)

    def add_certificate(self):
        """Adds certificate on the BTS to authenticate secgw"""
        self.commissioning.add_certificate()

    def _get_no_of_vlans(self):
        command = "sudo ifconfig -a | grep " + "'" + "eth3.*" + "'" + " | wc -l 2> /dev/null"
        return int(self.executor.execute_command_on_secgw(command)) - 1

    def _get_embypass_state(self):
        search_expression = "ipSecEmBypassState | cut -d'>' -f2 | cut -d'<' -f1"
        found_state = self.trs_config.search_trs_parameter_soam(search_expression)
        return found_state.strip()


class SecGwIpsec(CommonIpsec):

    """ All secgw Ipsec methods in this class"""
    ipsec_conf_path = '/etc/ipsec.conf'
    IPSEC_CONF_FILE = 'ipsec.conf'
    TMP_IPSEC_CONF_FILE = 'tmp_ipsec.conf'

    def __init__(self, executor, sec_gw_ip):
        self.executor = executor
        self.commissioning = Commissioning()
        self.cmd_builder = CommandBuilder()
        self.sec_gw_ip = sec_gw_ip

    def enable(self, ipsec_conf_file):
        """Enables Ipsec on secgw"""
        self.executor.execute_command_on_secgw('sudo ipsec start')

    def check_all_states(self):
        """Checks ipsec and connections states"""
        self.check_state('enabled')
        self.verify_connections_established()

    def check_state(self, expected_state):
        """Raises error if the expected ipsec state is not found"""
        found_state = self._get_state()
        self._assert_state(expected_state, found_state)

    def _get_state(self):
        """Returns true | false"""
        try:
            self.executor.execute_command_on_secgw('sudo ipsec status')
            return 'enabled'
        except CalledProcessError as err:
            return 'enabled' if err.returncode == 1 else 'disabled'

    def verify_connections_established(self, conn=(50, 60, 70)):
        """ Raises exception if connections are not established on Secgw """
        states = self.get_connections_states(conn)
        if any((status == 'not established' or espspi is None for status, espspi in states.values())):
            raise IpSecConnectionError('On Secgw', states)

    def get_connections_states(self, conn=(50, 60, 70)):
        """Returns connection(s) status"""
        console_output = self.get_ipsec_status()
        return self._parse_connections_states(conn, console_output)

    def get_ipsec_status(self):
        """Returns ipsec status"""
        try:
            return self.executor.execute_command_on_secgw('sudo ipsec status')
        except CalledProcessError:
            raise IpSecDisabledError('on secgw')

    def disable(self):
        """Stops ipsec on secgw"""
        self.executor.execute_command_on_secgw('sudo ipsec stop')

    def restart(self):
        """Restarts ipsec on secgw"""
        self.executor.execute_command_on_secgw('sudo ipsec restart')

    def modify_ipsec_policy_parameters_on_secgw(self, connections, **parameters):
        """Modifies Ipsec policy parameters for the specified connection(s) with the specified parameter name & values on Secgw"""
        connections = self._interpret_connection_numbers(connections)
        for conn in connections:
            for parameter in parameters.keys():
                self._edit_ipsec_conf_file(conn, parameter, parameters[parameter])

    def _update_ipsec_conf_file(self, ipsec_conf_file):
        if ipsec_conf_file != 'default':
            self.ipsec_conf_path = self._get_ipsec_conf_path()
            self.executor.execute_command_on_secgw("sudo chmod 777 " + self.ipsec_conf_path)
            self.executor.execute_command_locally("sshpass -p " + "ute" + " sudo scp " + ipsec_conf_file
                                                  + " ute@" + self.sec_gw_ip + ":" + self.ipsec_conf_path)

    def _edit_ipsec_conf_file(self, conn, parameter, value):
        self.ipsec_conf_path = self._get_ipsec_conf_path()
        sedcommand = self._build_sed_command(conn, parameter, value)
        self.executor.execute_command_on_secgw(sedcommand)
        self.executor.execute_command_on_secgw('sudo  mv {tmpfile} {conf_file}'.format(tmpfile=self.TMP_IPSEC_CONF_FILE,
                                                                                       conf_file=self.ipsec_conf_path))

    def _build_sed_command(self, conn, param_name, new_value):
        param_name, new_value = self._escape_special_chars(param_name, new_value)
        command_template = self._get_command_template(conn, param_name, new_value)
        command = command_template.format(conn_num=conn, param=param_name, val=new_value, conf_file=self.ipsec_conf_path,
                                          tmpfile=self.TMP_IPSEC_CONF_FILE)
        return command

    def _get_command_template(self, conn, param_name, new_value):
        if self._check_if_param_is_new(conn, param_name):
            return self.cmd_builder.build_append_command_template()
        elif new_value.strip().lower() == 'comment':
            return self.cmd_builder.build_comment_command_template()
        elif new_value.strip().lower() == 'uncomment':
            return self.cmd_builder.build_uncomment_command_template()
        else:
            return self.cmd_builder.build_replace_command_template()

    def _check_if_param_is_new(self, conn, param_name):
        awkcommand_template = self.cmd_builder.build_awk_command_template()
        awkcommand = awkcommand_template.format(conn_num=conn, param=param_name, conf_file=self.ipsec_conf_path)
        result = self.executor.execute_command_on_secgw(awkcommand)
        if int(result) > 0:
            return False
        else:
            return True

    def _interpret_connection_numbers(self, connections):
        if connections[0].strip().lower() == 'all':
            return ['conn50', 'conn60', 'conn70', 'conn80']
        elif connections[0].strip().lower() == 'default':
            return [r'\%default']
        else:
            connections = ['conn' + conn for conn in connections]
            return connections

    def _get_ipsec_conf_path(self):
        ipsec_bin_file = self.executor.execute_command_on_secgw('sudo which ipsec')
        # ipsec_bin_file = string.replace(ipsec_bin_file, '\n', '')
        ipsec_bin_file = ipsec_bin_file.replace("\n", "")
        ipsec_conf_path = self.executor.execute_command_on_secgw('cat {} | grep IPSEC_CONFDIR= | cut -d\'=\' -f2'.format(ipsec_bin_file))
        # ipsec_conf_path = string.replace(ipsec_conf_path, '"', '')
        ipsec_conf_path = ipsec_conf_path.replace('"', '')
        # ipsec_conf_path = string.replace(ipsec_conf_path, '\n', '')
        ipsec_conf_path = ipsec_conf_path.replace('\n', '')
        ipsec_conf_path = os.path.join(ipsec_conf_path, self.IPSEC_CONF_FILE)
        return ipsec_conf_path

    def _escape_special_chars(self, param_name, new_value):
        # param_name = string.replace(param_name, r'/', r'\/')
        # new_value = string.replace(new_value, r'/', r'\/')
        param_name = param_name.replace(r'/', r'\/')
        new_value = new_value.replace(r'/', r'\/')
        return param_name, new_value


class ControlServer(object):

    """ All control server methods in this class"""

    def __init__(self, executor):
        self.executor = executor

    def bring_control_server_up(self, ip_version):
        """Creates a virtual interface on secgw for emergency by-pass control"""
        if ip_version == 4:
            self.executor.execute_command_locally('sudo ifconfig eth3:0 10.0.1.10 netmask 255.255.255.0 up')
        elif ip_version == 6:
            self.executor.execute_command_locally('sudo ifconfig eth3 inet6 add fc00::10/116')

    def bring_control_server_down(self, ip_version):
        """Brings down the virtual interface on vm"""
        if ip_version == 4:
            self.executor.execute_command_locally('sudo ifconfig eth3:0 down')
        elif ip_version == 6:
            self.executor.execute_command_locally('sudo ifconfig eth3 inet6 del fc00::10/116')
